mapper.sql:
case_id = #{caseId}
AND EXISTS (
    SELECT 1 FROM cases WHERE id = #{caseId} AND user_id = #{userId}
)

mapper.insert:
INSERT INTO case_interactions (case_id, run_id, interaction_type, prompt, options)
SELECT run.case_id, run.id, #{interactionType}, #{prompt},
       CAST(#{options, jdbcType=VARCHAR} AS jsonb)
FROM orchestrator_runs run
WHERE run.id = #{runId}
  AND run.case_id = #{caseId}

mapper.select:
SELECT id, case_id, run_id, interaction_type, prompt, options, response,
       case_interactions_status, created_at, responded_at
FROM case_interactions
WHERE run_id = #{runId}
  AND EXISTS (
      SELECT 1 FROM cases WHERE id = case_interactions.case_id AND user_id = #{userId}
  )
ORDER BY created_at DESC, id DESC
LIMIT 1
